import {renderEqsDebugControls} from './eqs-debug-controls.js';
import {effectScalingEditor} from './effect-scaling-editor.js';
import {renderAbilitySetEditor} from './ability-set-editor.js';
import {assetTypes,validAsset} from './asset-documents.js';
import {bakeNavigationMesh} from './navigation-mesh.js';
import {terrainMesh} from './world-assets.js';
const labels={plane:'생성 평면',attributes:'속성',abilities:'시작 능력',base:'기본값',cues:'게임플레이 Cue',on:'발생 시점',event:'수신 이벤트',cooldown:'쿨다운',duration:'지속 시간 (-1 무한)',costs:'비용',attribute:'속성',amount:'비용',requiredTags:'필수 태그',blockedTags:'차단 태그',grantedTags:'부여 태그',effects:'적용 효과',onActivate:'활성 이벤트',onEnd:'종료 이벤트',period:'실행 주기',executeOnApply:'부착 시 실행',stackLimit:'중첩 상한',stackPolicy:'중첩 정책',modifiers:'속성 변경',operation:'연산',magnitude:'값',generator:'생성기',radius:'반경',spacing:'간격',count:'수량',tests:'테스트',min:'최소',max:'최대',weight:'가중치',reference:'기준',tag:'태그',fallback:'기본 문화권',entries:'문자열',translations:'번역',culture:'문화권',text:'텍스트',one:'단수',other:'복수',key:'키',styles:'스타일',name:'이름',fontSize:'글자 크기',color:'색상',background:'배경',accent:'강조',padding:'여백',font:'글꼴',maxSlope:'최대 경사',links:'오프 메시 링크',start:'시작',end:'종료',bidirectional:'양방향',cost:'이동 비용',enabled:'활성화'};
const choices={plane:['XZ','XY'],on:['activate','end','apply','period','remove'],stackPolicy:['refresh','extend','independent','reject'],operation:['add','multiply','override'],generator:['grid','ring','actors'],type:['distance','dot','height','trace','tag'],reference:['origin','context']};
export const structuredAssetKinds=['ability','effect','abilityset','environmentquery','navmesh','stringtable','uistyle'];
export function renderStructuredAssetEditor(element,doc,files,hooks){
  if(doc.kind==='abilityset')return renderAbilitySetEditor(element,doc,files,hooks);
  const document=element.ownerDocument,effectCurves=new Map(),effectHooks={...hooks,readAsset:path=>{if(!effectCurves.has(path))effectCurves.set(path,Promise.resolve().then(()=>hooks.readAsset(path)));return effectCurves.get(path);}};let selectedSource='';element.replaceChildren();const heading=document.createElement('header');heading.className='asset-editor-heading';const title=document.createElement('h2');title.textContent=assetTypes[doc.kind].label+' · '+doc.data.name;heading.append(title);const form=document.createElement('div');form.className='asset-form';element.append(heading,form);
  const edit=fn=>{try{const next=structuredClone(doc.data);if(['ability','effect'].includes(doc.kind))next.cues??=[];fn(next);if(!validAsset(doc.kind,next))throw Error('이름·참조·값 범위를 확인하세요.');if(JSON.stringify(next)===JSON.stringify(doc.data))return;hooks.before();doc.data=next;hooks.change();renderStructuredAssetEditor(element,doc,files,hooks);}catch(e){hooks.error(e.message);}};
  const at=(d,path)=>path.reduce((a,k)=>a[k],d),set=(path,value)=>edit(d=>{at(d,path.slice(0,-1))[path.at(-1)]=value;});
  const sample=(key,list)=>key==='attributes'?{name:'Attribute'+(list.length+1),base:100,min:0,max:100}:key==='abilities'?files.find(f=>f.kind==='ability')?.path:key==='cues'?{tag:'Cue.New'+(list.length+1),event:'OnCue',on:doc.kind==='ability'?'activate':'apply'}:key==='costs'?{attribute:'Mana',amount:10}:key==='modifiers'?{attribute:'Health',operation:'add',magnitude:10}:key==='tests'?{type:'distance',min:0,max:100000,weight:-1,reference:'context'}:key==='links'?{start:[0,0,0],end:[1,0,0],bidirectional:true,cost:1,enabled:true}:key==='entries'?{key:'Key'+(list.length+1),translations:[{culture:'ko',text:'',one:'',other:''}]}:key==='translations'?{culture:['en','ja','fr','de','es','zh','ar'].find(c=>!list.some(t=>t.culture===c))||'ko-KR',text:'',one:'',other:''}:key==='styles'?{name:'Style'+(list.length+1),fontSize:24,color:'#e4e9ef',background:'#263443',accent:'#589ad6',radius:4,padding:8,font:''}:key==='effects'?files.find(f=>f.kind==='effect')?.path:'Tag.New'+(list.length+1);
  function build(parent,value,path){const key=path.at(-1);if(doc.kind==='navmesh'&&['vertices','indices','costs'].includes(key))return;
    if(Array.isArray(value)){const section=document.createElement('section'),header=document.createElement('div'),label=document.createElement('h3');label.textContent=(labels[key]||key)+' · '+value.length;header.className='form-section-heading';header.append(label);section.append(header);parent.append(section);if(value.length===3&&['start','end'].includes(key)){value.forEach((v,i)=>build(section,v,[...path,i]));return;}const add=document.createElement('button');add.textContent='추가';add.type='button';add.onclick=()=>edit(d=>{const list=at(d,path),next=sample(key,list);if(next===undefined)throw Error('적용할 효과를 먼저 만드세요.');list.push(next);});header.append(add);value.forEach((v,i)=>{const row=document.createElement('details');row.open=value.length<=8;const summary=document.createElement('summary');summary.textContent=v?.name||v?.key||v?.attribute||v?.culture||String(i+1);row.append(summary);build(row,v,[...path,i]);const remove=document.createElement('button');remove.type='button';remove.textContent='삭제';remove.onclick=()=>edit(d=>at(d,path).splice(i,1));row.append(remove);section.append(row);});return;}
    if(doc.kind==='effect'&&path[0]==='modifiers'&&path.length===2&&value&&typeof value==='object'){parent.dataset.effectModifier=String(path[1]);for(const key of ['attribute','operation','magnitude'])build(parent,value[key],[...path,key]);parent.append(effectScalingEditor(document,doc,path[1],files,effectHooks,edit));return;}
    if(value&&typeof value==='object'){for(const [key,v] of Object.entries(value))if(key!=='version')build(parent,v,[...path,key]);return;}
    const label=document.createElement('label');label.textContent=labels[key]||(['start','end'].includes(path.at(-2))?['X','Y','Z'][key]:key);let input;
    const assetKind=key==='font'?'font':path.at(-2)==='effects'?'effect':path.at(-2)==='abilities'?'ability':null,options=key==='on'?choices.on.filter(v=>(doc.kind==='ability'?['activate','end']:['apply','period','remove']).includes(v)):choices[key];
    if(assetKind||options){input=document.createElement('select');for(const v of assetKind?['',...files.filter(f=>f.kind===assetKind).map(f=>f.path)]:options){const option=document.createElement('option');option.value=v;option.textContent=v||'없음';input.append(option);}input.value=String(value);}
    else{input=document.createElement('input');input.type=typeof value==='boolean'?'checkbox':typeof value==='number'?'number':typeof value==='string'&&/^#[\da-f]{6}$/i.test(value)?'color':'text';if(input.type==='checkbox')input.checked=value;else input.value=value;input.step='any';}
    input.setAttribute('aria-label',label.textContent);input.onchange=()=>set(path,typeof value==='boolean'?input.checked:typeof value==='number'?Number(input.value):input.value);label.append(input);parent.append(label);
  }
  if(doc.kind==='environmentquery'&&hooks.query)renderEqsDebugControls(form,doc,hooks);
  build(form,doc.data,[]);if(['environmentquery','navmesh'].includes(doc.kind)&&doc.data.plane===undefined)build(form,'XZ',['plane']);if(['ability','effect'].includes(doc.kind)&&doc.data.cues===undefined){build(form,[],['cues']);}
  if(doc.kind==='navmesh'){const section=document.createElement('section'),info=document.createElement('p'),source=document.createElement('select'),bake=document.createElement('button');info.dataset.navmeshSummary='';source.dataset.navmeshSource='';source.setAttribute('aria-label','베이크 원본 메시');bake.dataset.navmeshBake='';info.textContent=(doc.data.plane||'XZ')+' · '+doc.data.vertices.length+' 정점 · '+doc.data.indices.length/3+' 삼각형';for(const file of files.filter(f=>['mesh','terrain'].includes(f.kind))){const option=document.createElement('option');option.value=file.path;option.textContent=file.name;source.append(option);}source.onchange=()=>selectedSource=source.value;bake.textContent='메시에서 굽기';bake.onclick=async()=>{try{const path=selectedSource||source.value;if(!path)throw Error('원본 메시·지형을 선택하세요.');const input=await hooks.readAsset(path),data=bakeNavigationMesh(path.endsWith('.hbterrain.json')?terrainMesh(input):input,{name:doc.data.name,maxSlope:doc.data.maxSlope,plane:doc.data.plane||'XZ'});edit(d=>Object.assign(d,data,{links:d.links}));}catch(e){hooks.error(e.message);}};section.append(info,source,bake);form.prepend(section);}
}
